import{I as r,o as g,c as b,j as e,a as o,J as n,w as s,b6 as i,cN as q,cO as h,cP as f,cQ as v,cR as y,cS as x,cT as _,cU as A,cV as k,cW as j,cX as I,cY as P,cZ as E,c_ as z,c$ as C,d0 as S,d1 as D,d2 as T,d3 as R,k as L}from"./chunks/framework.BUXTSoD9.js";import{r as N}from"./chunks/relatedArticles.DIHQAH-1.js";const V={style:{margin:"50px 0"}},w={style:{margin:"50px 0"}},M={style:{margin:"50px 0"}},U={style:{margin:"50px 0"}},B=JSON.parse('{"title":"Construyendo un prototipo - Del analisis de negocio al prototipo multipagina","description":"Experimenta el ciclo completo desde el analisis de negocio hasta la implementacion de un prototipo de producto multipagina.","frontmatter":{"title":"Construyendo un prototipo - Del analisis de negocio al prototipo multipagina","description":"Experimenta el ciclo completo desde el analisis de negocio hasta la implementacion de un prototipo de producto multipagina."},"headers":[],"relativePath":"es-es/stage-1/building-prototype/index.md","filePath":"es-es/stage-1/building-prototype/index.md"}'),F={name:"es-es/stage-1/building-prototype/index.md"},J=Object.assign(F,{setup(G){const d="Aproximadamente <strong>8 horas</strong>",c=N["es-es/stage-1/building-prototype"]??[];return(H,a)=>{const u=r("ChapterIntroduction"),t=r("StepBar"),l=r("ClientOnly"),p=r("el-card"),m=r("RelatedArticlesSection");return g(),b("div",null,[a[5]||(a[5]=e("h1",{id:"construyendo-un-prototipo",tabindex:"-1"},[o("Construyendo un prototipo "),e("a",{class:"header-anchor",href:"#construyendo-un-prototipo","aria-label":"Permalink to “Construyendo un prototipo”"},"​")],-1)),a[6]||(a[6]=e("h2",{id:"resumen-del-capitulo",tabindex:"-1"},[o("Resumen del capitulo "),e("a",{class:"header-anchor",href:"#resumen-del-capitulo","aria-label":"Permalink to “Resumen del capitulo”"},"​")],-1)),n(u,{duration:d,tags:["Analisis de negocio","Diseno de prototipo","Programacion asistida por IA","Aplicacion multipagina"],coreOutput:"1 prototipo de espacio de trabajo de materiales de e-commerce",expectedOutput:"Prototipo web interactivo"},{default:s(()=>[...a[0]||(a[0]=[e("p",null,[o("En el capitulo anterior, aprendimos como "),e("strong",null,"encontrar buenas ideas"),o(": partiendo de las necesidades de los usuarios, encontrar direcciones por las que alguien este dispuesto a pagar. Pero encontrar la direccion es solo el primer paso; "),e("strong",null,"lo que realmente pone a prueba al product manager es: como convertir necesidades vagas en un producto util.")],-1),e("p",null,[o("Este capitulo va a resolver un "),e("strong",null,"problema real"),o(': tu jefe te dice "usa IA para mejorar la eficiencia de publicar productos en plataformas de e-commerce" -- como lo conviertes en un '),e("strong",null,"prototipo de producto util"),o("?")],-1),e("p",null,[o("A diferencia de hacer un juego de Snake o una calculadora, "),e("strong",null,"en negocios reales no puedes inventar funcionalidades de la nada"),o(":")],-1),e("ol",null,[e("li",null,[e("strong",null,"Aclarar los puntos de dolor"),o(': hablar con el equipo de operaciones, extraer de la vaga "mejorar la eficiencia" los '),e("strong",null,"verdaderos puntos de dolor")]),e("li",null,[e("strong",null,"Elegir lo mas importante"),o(": de todos los problemas, resolver primero "),e("strong",null,"el mas doloroso"),o(", sin intentar hacer todo de una vez")]),e("li",null,[e("strong",null,"Validar rapidamente"),o(": usar el AI IDE para hacer primero un "),e("strong",null,"prototipo de una sola pagina"),o(", y una vez que funcione, expandirlo a multipagina")]),e("li",null,[e("strong",null,"Hacer algo util"),o(": entregar finalmente un "),e("strong",null,"espacio de trabajo de materiales de e-commerce que se pueda demostrar y operar")])],-1),e("p",null,[o("Aprenderemos la "),e("strong",null,"transicion de hacer juguetes a hacer aplicaciones"),o(", y a "),e("strong",null,"empatizar y pensar en las necesidades reales de los clientes"),o(".")],-1)])]),_:1}),a[7]||(a[7]=e("div",{class:"info custom-block"},[e("p",{class:"custom-block-title"},"Nota"),e("p",null,"En este capitulo pueden aparecer terminos de negocio. Si no los entiendes, puedes preguntar a la IA para obtener una explicacion.")],-1)),e("div",V,[n(l,null,{default:s(()=>[n(t,{active:0,items:[{title:"Analisis de necesidades",description:"De lo vago a lo concreto"},{title:"Validacion de una pagina",description:"La funcionalidad central toma forma"},{title:"Expansion multipagina",description:"Completar la estructura de la aplicacion"},{title:"Mejora estetica",description:"Mejorar la experiencia del usuario"}]})]),_:1})]),a[8]||(a[8]=i('<h2 id="_1-definir-los-requisitos-antes-de-escribir-codigo" tabindex="-1">1. Definir los requisitos antes de escribir codigo <a class="header-anchor" href="#_1-definir-los-requisitos-antes-de-escribir-codigo" aria-label="Permalink to “1. Definir los requisitos antes de escribir codigo”">​</a></h2><p>En los tutoriales anteriores, usamos AI IDE para generar facilmente el juego de Snake y otros juegos pequenos, pero estos solo pueden considerarse proyectos de juguete y no se pueden aplicar al trabajo y la vida cotidiana. Si queremos que las capacidades de IA sean realmente utiles para todos, deberiamos combinar la programacion Vibe Coding con escenarios de la vida real y del trabajo.</p><p>En el capitulo anterior aprendimos como encontrar <strong>buenas ideas por las que la gente este dispuesta a pagar</strong>, pero encontrar la direccion es solo el comienzo. Cuando realmente haces un producto, descubres que: <strong>saber &quot;que hacer&quot; y saber &quot;como hacerlo&quot; tienen una enorme brecha entre ellos.</strong></p><p>Esta brecha es la <strong>concrecion de los requisitos</strong>.</p><p>Por ejemplo, en clase o en proyectos personales, a menudo empezamos con la funcion ejecutable mas simple:</p><ul><li>&quot;Haz un tablero kanban, pon las tareas en una lista.&quot;</li><li>&quot;Hazme una herramienta de dibujo.&quot;</li><li>&quot;Hazme un software para recoger cuestionarios.&quot;</li></ul><p>Estas a menudo son solo una herramienta, un modulo funcional, ni siquiera pueden considerarse un problema de negocio claro. Lo mas critico es que <strong>estas ideas a menudo son solo &quot;tu crees que son utiles&quot;, no &quot;los usuarios realmente las necesitan&quot;.</strong></p><p>En proyectos empresariales o de startup, los product managers e ingenieros suelen partir de una proposicion de negocio mas grande. Por ejemplo, podemos suponer este escenario:</p>',8)),n(p,{shadow:"hover",style:{"border-left":"5px solid #409EFF","background-color":"#ecf5ff",margin:"20px 0"}},{default:s(()=>[...a[1]||(a[1]=[e("div",{style:{"font-weight":"bold",color:"#303133","margin-bottom":"10px"}},"Escenario de negocio:",-1),e("div",{style:{color:"#606266","line-height":"1.6"}},[e("p",null,"Eres el product manager de operaciones de e-commerce de una tienda. Tu jefe te ha dado una proposition vaga pero con mucha presion:"),e("p",{style:{"font-style":"italic","margin-top":"10px"}},'"Ahora todo el mundo en las cuentas oficiales esta usando IA para hacer imagenes y textos, parece muy facil. Ayudame con esto, para que seamos mas eficientes cuando subamos productos nuevos al e-commerce de TikTok."')],-1)])]),_:1}),a[9]||(a[9]=i(`<p>En este momento puedes pensar: &quot;Jefe, estas sonando otra vez!&quot; Sin embargo, en el trabajo real, este tipo de decisiones vagas con una sola frase son muy comunes, incluso mas frecuentes que las veces que pides te con leche a la semana. Por lo tanto, para ser un buen profesional (y mas aun si eres el CEO de una nueva startup), debemos aprender a pasar de hacer herramientas para nosotros mismos a hacer prototipos de productos reales.</p><p>Como hemos aprendido AI IDE, si lo piensas bien, este requisito es bastante simple: solo tienes que darle un prompt a la IA basado en esto, pasarlo al Agent y ya esta, no?</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Por favor refierete a mi necesidad xxxx,</span></span>
<span class="line"><span>ayudame a disenar un espacio de trabajo de materiales de e-commerce,</span></span>
<span class="line"><span>que incluya funciones de generacion y gestion de materiales como descripciones de productos, imagenes y videos.</span></span></code></pre></div><p>Si emocionado conviertes directamente este requisito en un prototipo y se lo envias al jefe -- felicidades, tu bonificacion de este trimestre acaba de ser cancelada!</p><p><strong>Por que? Este es el punto de dolor central que vamos a resolver:</strong></p><p>Antes aprendimos AI IDE haciendo proyectos de juguete como el juego de Snake o una calculadora -- funcionalidades simples, tu sabes lo que quieres, y lo haces para ti mismo. Pero <strong>los escenarios de negocio reales son completamente diferentes</strong>:</p><ul><li><strong>Tu no eres el usuario</strong>: el jefe quiere &quot;mejorar la eficiencia&quot;, pero no sabes como trabaja exactamente el equipo de operaciones cada dia ni donde se atascan;</li><li><strong>La IA tampoco entiende el negocio</strong>: si le das a la IA un requisito vago, solo puede adivinar basandose en conocimientos generales. Lo que produce puede parecer correcto, pero en realidad no se puede usar;</li><li><strong>Una buena idea no equivale a un buen producto</strong>: crees que &quot;anadir una funcion de generacion con IA&quot; es genial, pero los usuarios puede que no lo necesiten, o que sea mas complicado de usar que antes.</li></ul><p><strong>Por eso debemos aprender a &quot;pasar de tener una idea a entender a los usuarios&quot;</strong> Solo cuando tu creatividad resuelve realmente los problemas de los demas, cuando preguntas, cuando profundizas en el entendimiento del negocio, puedes crear algo verdaderamente valioso. (Una buena idea puede ser incluso mas importante que una buena tecnologia).</p><h3 id="_1-1-de-la-imaginacion-a-la-realidad-aprender-a-hacer-preguntas-sobre-el-negocio" tabindex="-1">1.1 De la imaginacion a la realidad: aprender a hacer preguntas sobre el negocio <a class="header-anchor" href="#_1-1-de-la-imaginacion-a-la-realidad-aprender-a-hacer-preguntas-sobre-el-negocio" aria-label="Permalink to “1.1 De la imaginacion a la realidad: aprender a hacer preguntas sobre el negocio”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Primero aclaremos: que es un requisito? Que es un negocio?</p><p>Un <strong>requisito</strong> es lo que el usuario realmente quiere, los problemas que encuentra, lo que quiere resolver. Por ejemplo, &quot;el jefe quiere que publique productos mas rapido&quot;, eso es un requisito.</p><p>Un <strong>negocio</strong> es lo que los usuarios hacen realmente cada dia, su forma de trabajar. Por ejemplo, lo que hace el equipo de operaciones de e-commerce cada dia: publicar productos, cambiar precios, hacer imagenes, ver datos... todo esto es negocio.</p><p><strong>Por que prestar atencion al negocio?</strong> Porque si no entiendes el negocio, la herramienta que hagas puede ser &quot;parece buena, pero nadie la usa&quot;. Solo entendiendo realmente como trabajan los usuarios cada dia y donde se atascan, puedes hacer algo que realmente les ayude.</p></div><p>Desde la perspectiva mas simple, puedes empezar por preguntarte:</p><ul><li>Cuando el jefe dice &quot;<strong>mas eficiencia</strong>&quot;, que significa exactamente? Quiere <strong>hacerlo mas rapido</strong>? O quiere <strong>gastar menos</strong>? O quiere <strong>vender mas</strong>?</li><li>Como se publican los productos ahora? <strong>Donde esta el problema</strong>?</li><li>Cuantos <strong>productos nuevos</strong> hay que hacer cada dia? Cuantas <strong>imagenes</strong> y cuanto <strong>texto</strong> por producto?</li><li>En el trabajo actual, <strong>que es lo mas molesto</strong>, <strong>lo que menos quieres hacer</strong>?</li></ul><p>Pero estas son preguntas que suponemos; debemos preguntar directamente al equipo de operaciones de e-commerce de primera linea: &quot;Cuales son sus dificultades y en que se enfocan?&quot; A traves de la comunicacion, obtendremos respuestas mas precisas:</p><div class="info custom-block"><p class="custom-block-title">Resultado de la entrevista real de negocio</p><p>Preguntamos a personas que hacen operaciones de e-commerce, y nos contaron estas frustraciones:</p><p><strong>1. Demasiadas cosas y muy dispersas</strong></p><ul><li>Una persona tiene que gestionar varias tiendas, cada tienda tiene muchos productos que preparar;</li><li>Cada dia va de aqui para alla: <strong>publicar productos nuevos</strong>, <strong>cambiar precios</strong>, <strong>hacer imagenes</strong>, <strong>ver datos</strong>; una cosa no termina y ya hay que hacer otra.</li></ul><p><strong>2. Hacer contenido no es hacerlo bien de una vez, sino ir probando</strong></p><ul><li>Primero usan <strong>las imagenes del fabricante</strong>, <strong>materiales usados antes</strong> o <strong>imagenes de referencia encontradas en internet</strong> para <strong>publicar</strong> rapidamente el producto y probar;</li><li>Gastan un poco en promocion para <strong>ver si alguien compra</strong>;</li><li>Solo para los <strong>productos que venden bien</strong>, se toman el tiempo de hacer buenas imagenes, escribir descripciones detalladas y grabar videos.</li></ul></div><p>Despues de entrevistar al equipo de negocio, sentimos entusiasmo, porque ahora realmente podemos hacer un prototipo perfecto que se ajuste al negocio! -- Nos equivocamos de nuevo. Si intentamos &quot;satisfacer todas las demandas de una vez&quot;, el producto sera muy grande y dificil de implementar dentro del tiempo del curso. Por lo tanto, necesitamos organizar y priorizar aun mas, para encontrar el verdadero punto de dolor central.</p><h3 id="_1-2-de-la-divergencia-a-la-convergencia-identificar-el-punto-de-dolor-central-y-la-funcionalidad-del-negocio" tabindex="-1">1.2 De la divergencia a la convergencia: identificar el punto de dolor central y la funcionalidad del negocio <a class="header-anchor" href="#_1-2-de-la-divergencia-a-la-convergencia-identificar-el-punto-de-dolor-central-y-la-funcionalidad-del-negocio" aria-label="Permalink to “1.2 De la divergencia a la convergencia: identificar el punto de dolor central y la funcionalidad del negocio”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Por que &quot;converger&quot;? Que es un &quot;punto de dolor&quot;?</p><p><strong>Hay muchos problemas, pero cual hacemos primero?</strong></p><p>Los usuarios pueden contarte un monton de problemas: A tambien es molesto, B tambien es molesto, C tambien... Pero si intentas resolver todos los problemas a la vez, probablemente no hagas bien ninguno. Por eso hay que <strong>converger</strong>: elegir de todos los problemas el <strong>mas doloroso, el mas urgente y el mas resoluble</strong> para empezar.</p><p><strong>Que es un punto de dolor?</strong> Es el problema concreto que los usuarios <strong>mas odian, en el que mas tiempo gastan y que mas quieren resolver</strong>. No es &quot;me parece util&quot;, sino algo de lo que los usuarios <strong>se quejan todos los dias y que les duele cada vez que hacen</strong>.</p></div><p>A traves de la entrevista anterior, descubrimos que las operaciones encuentran muchos problemas: el ritmo interrumpido por promociones, tener que gestionar multiples tiendas, ir de publicar/cambiar precios/hacer imagenes/ver datos de un lado a otro...</p><p>Si intentamos &quot;resolver todos estos problemas&quot;, terminaremos con una herramienta <strong>grande y completa pero inutil</strong>.</p><p>Vamos a clasificar estos problemas (puedes pedirle ayuda a la IA); aproximadamente hay tres categorias:</p><ol><li><strong>Problemas de ritmo</strong>: cuando publicar, cuando ajustar precios;</li><li><strong>Problemas de eficiencia</strong>: como gestionar bien multiples tiendas y multiples productos a la vez;</li><li><strong>Problemas de contenido</strong>: como hacer rapidamente imagenes y textos de productos.</li></ol><p>Para nuestro curso, lo mas adecuado para resolver primero es la <strong>categoria 3: el problema de hacer contenido</strong>. Pero &quot;hacer contenido rapidamente&quot; sigue siendo algo abstracto, asi que preguntamos al equipo de negocio donde se atascan especificamente:</p><div class="info custom-block"><p class="custom-block-title">El equipo de negocio dice: hay dos cosas mas dolorosas al hacer contenido</p><p><strong>Dolor 1: hacer imagenes y textos en lote es demasiado laborioso</strong></p><ul><li>Los materiales estan por todas partes: en la nube, en el historial de WeChat, en el backend de la plataforma... <strong>encontrarlos es muy dificil</strong>;</li><li>Hay que publicar muchos productos a la vez, <strong>no hay tiempo para hacerlos uno por uno con cuidado</strong>, solo se puede hacer algo rapido;</li><li>Los requisitos no son altos, <strong>con que se pueda ver y publicar</strong>, no necesita ser muy elaborado.</li></ul><p><strong>Dolor 2: las buenas soluciones no se pueden guardar y reutilizar</strong></p><ul><li>Los titulos y layouts que funcionaron bien antes, <strong>la proxima vez que se necesitan no se encuentran</strong>;</li><li>Las soluciones estan dispersas en el historial de chat y en enlaces de productos anteriores;</li><li>Cuando se necesitan hay que <strong>buscar un buen rato y copiar/pegar/modificar otro rato</strong>;</li><li>Falta una herramienta para <strong>guardar, gestionar y aplicar directamente</strong>.</li></ul></div><p>Basandose en estos dos puntos de dolor, vamos a hacer una pequena herramienta: <strong>ayudar al equipo de operaciones a hacer imagenes y textos en lote, y ademas poder guardar las buenas soluciones para usarlas directamente la proxima vez</strong>.</p><p>Solo hace dos cosas (puedes pedirle a la IA que las refine, recuerda ir recortando funcionalidades segun el feedback del negocio):</p><div class="info custom-block"><p class="custom-block-title">Funcionalidad 1: Generar en lote imagenes y textos de productos de e-commerce</p><p><strong>Para que sirve?</strong> Le das al sistema informacion del producto, y automaticamente te genera imagenes y textos que se pueden usar para publicar en plataformas de e-commerce (como TikTok, Taobao).</p><p><strong>Entrada</strong></p><table tabindex="0"><thead><tr><th>Tipo</th><th>Contenido</th></tr></thead><tbody><tr><td>Informacion del producto</td><td>Nombre, categoria, marca, material, talla, color, etc.</td></tr><tr><td>Imagenes del producto</td><td>Foto con fondo blanco o con escenario simple</td></tr><tr><td>Imagenes de referencia</td><td>Capturas de productos que se vendieron bien antes o enlaces de referencia</td></tr><tr><td>Forma de importar</td><td>Importar en lote via Excel, o rellenar directamente en la pagina</td></tr></tbody></table><p><strong>Salida (materiales de e-commerce generados)</strong></p><ul><li><strong>Imagen principal del producto</strong>: imagen de presentacion con puntos de venta en texto (la primera imagen que ve el usuario al desplazar)</li><li><strong>Titulo del producto</strong>: combinacion de palabras clave que se pueden buscar</li><li><strong>Texto de puntos de venta</strong>: 1-2 frases atractivas para los compradores</li><li>Todo es un producto final que <strong>con pequenos ajustes se puede publicar</strong></li></ul><p><strong>Resultado esperado</strong></p><ul><li>Antes: cada producto habia que hacerlo desde cero, imagen y texto</li><li>Ahora: pasas un lote de productos al sistema, y despues de generar borradores solo eliges y ajustas</li></ul></div><div class="info custom-block"><p class="custom-block-title">Funcionalidad 2: Guardar las buenas soluciones como plantillas</p><p><strong>Entrada</strong></p><table tabindex="0"><thead><tr><th>Tipo</th><th>Contenido</th></tr></thead><tbody><tr><td>Un conjunto completo</td><td>Imagen principal + titulo + texto</td></tr></tbody></table><p><strong>Salida</strong></p><table tabindex="0"><thead><tr><th>Funcion</th><th>Descripcion</th></tr></thead><tbody><tr><td>Aplicar</td><td>Al hacer un producto nuevo la proxima vez, generar automaticamente con la plantilla</td></tr><tr><td>Modificar</td><td>Cambiar directamente el titulo y el texto</td></tr><tr><td>Gestionar</td><td>Poner nombre, etiquetar (ej. &quot;plantilla de bolsos de hombre&quot;, &quot;titulo de promocion&quot;), para facilitar la busqueda</td></tr></tbody></table><p><strong>Resultado esperado</strong></p><ol><li>Importar un producto nuevo</li><li>Elegir: dejar que el sistema genere por defecto, o <strong>usar mi plantilla guardada</strong></li><li>El sistema aplica automaticamente el estilo de la plantilla, generando nuevas imagenes y textos</li></ol></div><hr><p><strong>Repasemos lo que acabamos de hacer:</strong></p><ol><li><strong>Primero hicimos preguntas</strong>: en lugar de empezar directamente a hacer, primero preguntamos al equipo de operaciones &quot;que es lo que mas les molesta&quot;;</li><li><strong>Encontramos los puntos de dolor</strong>: descubrimos que lo mas doloroso es &quot;hacer imagenes y textos es demasiado trabajoso&quot; y &quot;las buenas soluciones no se pueden guardar&quot;;</li><li><strong>Convergimos el alcance</strong>: no hacemos una plataforma grande y completa, solo hacemos dos funciones: &quot;generar imagenes y textos en lote + guardar plantillas&quot;.</li></ol><p><strong>Por que es importante hacer esto?</strong></p><p>Un error comun de los principiantes al hacer productos es: cuantas mas funcionalidades, mejor. Pero lo que los usuarios realmente necesitan es <strong>que se resuelva el problema mas doloroso</strong>. Mejor hacer una o dos funcionalidades que realmente ayuden al usuario que un monton que no funcionen bien.</p><p><strong>El nucleo del pensamiento de producto y negocio:</strong></p><ul><li>No pienses &quot;creo que el usuario necesita esto&quot;</li><li>Ve y pregunta al usuario &quot;que haces cada dia? Donde te duele mas?&quot;</li><li>De todos los problemas, <strong>converge</strong> al mas doloroso y mas resoluble</li><li>Haz primero la <strong>version minima usable</strong>, y luego itera poco a poco</li></ul><p>Esto es lo que debemos aclarar antes de escribir codigo. El codigo es solo una herramienta; <strong>entender al usuario y encontrar el problema correcto</strong> es el primer paso.</p>`,35)),e("div",w,[n(l,null,{default:s(()=>[n(t,{active:1,items:[{title:"Analisis de necesidades",description:"De lo vago a lo concreto"},{title:"Validacion de una pagina",description:"La funcionalidad central toma forma"},{title:"Expansion multipagina",description:"Completar la estructura de la aplicacion"},{title:"Mejora estetica",description:"Mejorar la experiencia del usuario"}]})]),_:1})]),a[10]||(a[10]=i(`<h2 id="_2-producir-un-prototipo-en-10-minutos-dejar-que-el-ai-ide-implemente-la-funcionalidad-central" tabindex="-1">2. Producir un prototipo en 10 minutos: dejar que el AI IDE implemente la &quot;funcionalidad central&quot; <a class="header-anchor" href="#_2-producir-un-prototipo-en-10-minutos-dejar-que-el-ai-ide-implemente-la-funcionalidad-central" aria-label="Permalink to “2. Producir un prototipo en 10 minutos: dejar que el AI IDE implemente la &quot;funcionalidad central&quot;”">​</a></h2><div class="info custom-block"><p class="custom-block-title">Sobre el Plan de programacion</p><p>Si sientes que tu IDE actual no es lo suficientemente inteligente, o que te quedas sin cuota muy rapido, puedes comprar un <strong>plan de programacion</strong>. Puedes prever este articulo de referencia sobre el uso de Claude para programar.</p></div><p>Pensar es bueno, pero no hay que sobre-pensar. Dejemos de lado el exceso de reflexion y intentemos hacer un prototipo empezando con una sola pagina.</p><h3 id="_2-1-primer-paso-dile-a-la-ia-en-lenguaje-llano-que-quieres" tabindex="-1">2.1 Primer paso: dile a la IA en lenguaje llano que quieres <a class="header-anchor" href="#_2-1-primer-paso-dile-a-la-ia-en-lenguaje-llano-que-quieres" aria-label="Permalink to “2.1 Primer paso: dile a la IA en lenguaje llano que quieres”">​</a></h3><p>Al principio no busques el prompt perfecto; empieza con tu expresion mas natural. Como cuando le describes un requisito a un companero, dile a la IA en lenguaje llano lo que quieres hacer, y luego deja que la IA te ayude a optimizarlo en algo mas profesional.</p><h4 id="_2-1-1-empezar-con-una-descripcion-verbal-recomendado-para-principiantes" tabindex="-1">2.1.1 Empezar con una descripcion verbal (recomendado para principiantes) <a class="header-anchor" href="#_2-1-1-empezar-con-una-descripcion-verbal-recomendado-para-principiantes" aria-label="Permalink to “2.1.1 Empezar con una descripcion verbal (recomendado para principiantes)”">​</a></h4><p>Primero describe la idea con tus propias palabras, aunque sea rudimentario, no importa:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quiero hacer una herramienta que ayude a operaciones de e-commerce a generar automaticamente imagenes principales y textos de productos.</span></span>
<span class="line"><span>Los de operaciones normalmente tienen que hacer imagenes y escribir textos uno por uno, lo cual es muy molesto.</span></span>
<span class="line"><span>Mi idea es: suben la informacion del producto, el sistema genera un lote de borradores,</span></span>
<span class="line"><span>y los de operaciones eligen los buenos, los ajustan un poco y ya los pueden usar.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Primero hagamos la version mas simple: una pagina, a la izquierda se rellena la informacion del producto,</span></span>
<span class="line"><span>a la derecha se muestra el resultado generado. Que se puedan subir imagenes, rellenar texto,</span></span>
<span class="line"><span>y despues de generar, mostrar la vista previa de la imagen principal y el texto.</span></span></code></pre></div><p>A continuacion, enviale este texto a la IA (como ChatGPT, Claude, etc.) y pidele que te ayude a expandirlo. La IA normalmente te ayudara a completar detalles que no habias considerado, organizar tu idea mas claramente, y finalmente generar un prompt adecuado para enviar al AI IDE.</p><p>Puedes decirle a la IA asi:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ayudame a expandir la idea anterior, organizala en un documento de logica de negocio claro,</span></span>
<span class="line"><span>y luego genera un prompt adecuado para enviar a un AI IDE (como Cursor, Trae),</span></span>
<span class="line"><span>para generar el codigo de un prototipo de aplicacion de una sola pagina.</span></span></code></pre></div><p>La IA devolvera un conjunto de requisitos estructurados y el prompt correspondiente. Tu lo revisas, eliminas las funcionalidades innecesarias, confirmas que esta todo correcto, y luego lo usas para generar el codigo.</p><p>La ventaja de hacer esto es que lo que describes verbalmente es tu idea mas autentica, aunque puede faltar algunos detalles importantes. Cuando la IA te ayuda a expandir, puede preguntar cosas como &quot;quieres soportar subida en lote?&quot; que no habias pensado, ayudandote a validar mas. Puedes elegir conservar o eliminar funcionalidades poco practicas segun el feedback, y en iteraciones sucesivas determinar el prompt inicial para la IA.</p><h4 id="_2-1-2-saltarse-la-expansion-enviar-directamente-tu-documento-de-negocio-organizado-a-la-ia" tabindex="-1">2.1.2 Saltarse la expansion: enviar directamente tu documento de negocio organizado a la IA <a class="header-anchor" href="#_2-1-2-saltarse-la-expansion-enviar-directamente-tu-documento-de-negocio-organizado-a-la-ia" aria-label="Permalink to “2.1.2 Saltarse la expansion: enviar directamente tu documento de negocio organizado a la IA”">​</a></h4><p>Si ya has organizado el documento de logica de negocio en capitulos anteriores (por ejemplo, una descripcion de requisitos en lenguaje llano), puedes usar directamente el siguiente formato para enviarlo al AI IDE, ahorrando el paso intermedio de la expansion. Adecuado cuando los requisitos ya estan claros y quieres empezar a escribir codigo directamente:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ayudame a implementar una aplicacion de una sola pagina basandote en la logica de negocio, para validar la funcionalidad central.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>La logica de negocio es la siguiente:</span></span>
<span class="line"><span>1. Ayudar a operaciones a generar en lote la primera version de borradores de imagenes y textos:</span></span>
<span class="line"><span>- **Entrada (soporta subida directa e importacion en lote de materiales):**</span></span>
<span class="line"><span>  - Informacion basica del producto: nombre, categoria, marca, material, talla, color, publico objetivo, etc.;</span></span>
<span class="line"><span>  - Imagenes del producto: foto con fondo blanco / foto con escenario simple;</span></span>
<span class="line"><span>  - Cada generacion soporta subir capturas de productos exitosos anteriores o enlaces de referencia;</span></span>
<span class="line"><span>  - Soporta importar en lote via Excel, o rellenar/subir online en la pagina.</span></span>
<span class="line"><span>  - Soporta especificar en la pagina si guardar los materiales en la biblioteca, para facilitar el proximo uso</span></span>
<span class="line"><span>- **Salida (contenido que se puede publicar directamente o con pequenos cambios):**</span></span>
<span class="line"><span>  - Para cada producto, un borrador de imagen principal &quot;presentable, con puntos de venta basicos&quot;;</span></span>
<span class="line"><span>  - Un titulo &quot;con estructura razonable y palabras clave centrales&quot; + 1-2 frases de puntos de venta.</span></span>
<span class="line"><span>- **Cambio esperado en la forma de uso:**</span></span>
<span class="line"><span>  Pasar de empezar cada lote desde cero a pasar un lote de productos al sistema y usar los borradores generados para filtrar y ajustar.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Primero hagamos la primera funcionalidad; la segunda (biblioteca de plantillas) la anadiremos despues.</span></span></code></pre></div><h4 id="_2-1-3-el-enfoque-del-programador-avanzado-dejar-que-la-ia-escriba-el-prompt-del-prompt" tabindex="-1">2.1.3 El enfoque del programador (avanzado): dejar que la IA escriba &quot;el prompt del prompt&quot; <a class="header-anchor" href="#_2-1-3-el-enfoque-del-programador-avanzado-dejar-que-la-ia-escriba-el-prompt-del-prompt" aria-label="Permalink to “2.1.3 El enfoque del programador (avanzado): dejar que la IA escriba &quot;el prompt del prompt&quot;”">​</a></h4><p>Si quieres controlar mas finamente el proceso de generacion de codigo, primero puedes pedirle a la IA (como ChatGPT) que genere un prompt especifico para el AI IDE basandose en tus requisitos:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Basandote en la siguiente idea, ayudame a escribir un prompt para enviar a un coding Agent que generara codigo,</span></span>
<span class="line"><span>necesito usar este prompt para generar codigo.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Pega aqui tu descripcion de la logica de negocio]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requisitos:</span></span>
<span class="line"><span>1. El prompt debe incluir una descripcion clara del layout de la pagina</span></span>
<span class="line"><span>2. Definir claramente la estructura de datos y la logica de interaccion</span></span>
<span class="line"><span>3. Especificar el stack tecnologico (ej. React + Tailwind)</span></span>
<span class="line"><span>4. Listar los puntos de funcionalidad central a implementar</span></span></code></pre></div><p>Normalmente la IA generara un prompt estructurado como el siguiente: <img src="`+q+'" alt=""></p><p>Puedes modificar ligeramente este prompt y luego enviarlo al AI IDE para generar codigo.</p><h3 id="_2-2-segundo-paso-dejar-que-el-ai-ide-genere-codigo-directamente" tabindex="-1">2.2 Segundo paso: dejar que el AI IDE genere codigo directamente <a class="header-anchor" href="#_2-2-segundo-paso-dejar-que-el-ai-ide-genere-codigo-directamente" aria-label="Permalink to “2.2 Segundo paso: dejar que el AI IDE genere codigo directamente”">​</a></h3><h4 id="_2-2-1-preparacion-conocer-las-operaciones-basicas-del-ai-ide" tabindex="-1">2.2.1 Preparacion: conocer las operaciones basicas del AI IDE <a class="header-anchor" href="#_2-2-1-preparacion-conocer-las-operaciones-basicas-del-ai-ide" aria-label="Permalink to “2.2.1 Preparacion: conocer las operaciones basicas del AI IDE”">​</a></h4><p>Si aun no estas familiarizado con el uso basico del AI IDE (como Cursor, Trae, Windsurf, etc.), te recomendamos primero ver el <a href="/easy-vibe-ja-learning-map/zh-cn/appendix/2-development-tools/ide-basics/">tutorial basico de IDE</a> en el apendice, para entender como:</p><ul><li>Crear un nuevo proyecto</li><li>Conversar con el AI Agent</li><li>Entender el proceso de generacion de codigo de la IA</li></ul><h4 id="_2-2-2-empezar-a-generar-codigo" tabindex="-1">2.2.2 Empezar a generar codigo <a class="header-anchor" href="#_2-2-2-empezar-a-generar-codigo" aria-label="Permalink to “2.2.2 Empezar a generar codigo”">​</a></h4><p>Ya tienes el prompt inicial; usemos el primer estilo de prompt como ejemplo para que la IA nos ayude a generar codigo. Primero crea una ventana y la carpeta correspondiente, abre la carpeta (inicializa un nuevo proyecto en la direccion de carpeta que prefieras): <img src="'+h+'" alt=""><img src="'+f+'" alt=""></p><p>En la barra lateral, elige el modelo que prefieras (se recomiendan gemini, gpt, glm, kimi, minimax, etc.), e introduce el prompt obtenido en el primer paso: <img src="'+v+'" alt=""></p><p>Despues de hacer clic en generar, veremos la etapa familiar: la IA planificara la estructura de directorios del proyecto, los archivos necesarios y dara el contenido inicial de cada archivo.</p><div class="warning custom-block"><p class="custom-block-title">Nota especial: la IA puede detenerse esperando tu confirmacion</p><p>Durante el proceso de generacion, el AI Agent frecuentemente <strong>se detendra esperando tu input o confirmacion</strong>, por ejemplo:</p><ul><li>Preguntandote si quieres continuar al siguiente paso</li><li>Pidiendote que presiones Enter para confirmar una operacion</li><li>Preguntandote sobre alguna eleccion tecnica</li></ul><p><strong>Si ves que la IA no avanza, primero revisa la interfaz de chat para ver si esta esperando tu respuesta.</strong> Muchos principiantes creen que la IA esta pensando, cuando en realidad ya se detuvo esperandote. Responde activamente o presiona Enter, y la IA continuara trabajando.</p></div><p>Tambien recuerda presionar Enter para confirmar la informacion (de lo contrario se quedara esperando; algunos AI IDE no tienen este problema): <img src="'+y+'" alt=""></p><p>Si te encuentras con la siguiente situacion, significa que ya se ha iniciado un servicio local; necesitas hacer clic para saltar, de lo contrario te quedaras en esta pantalla (si despues de generar el codigo no aparece nada, necesitas decir activamente &quot;ayudame a iniciar este proyecto&quot;): <img src="'+x+'" alt=""></p><div class="info custom-block"><p class="custom-block-title">Explicacion del escenario</p><p><strong>Explicacion del escenario</strong>: usaste <code>npm create vite@latest</code> para crear un proyecto React + TypeScript (easy-vibe-web). Una vez completada la creacion, la computadora automaticamente &quot;ejecutara&quot; esta pagina web, para que puedas ver el efecto inmediatamente.</p><p><strong>Servicio local</strong>: se puede entender como que tu computadora ha abierto temporalmente una ventana de muestra de pagina web, que solo se ejecuta en tu computadora; los demas no pueden acceder.</p><p><strong>localhost (direccion local)</strong>: <code>localhost</code> significa &quot;esta computadora misma&quot;. Cuando el navegador accede a esta direccion, en realidad esta accediendo a la pagina web que se esta ejecutando en tu computadora.</p><p><strong>Puerto</strong>: el puerto se puede entender como un numero que se usa para distinguir diferentes servicios de paginas web que se ejecutan en la misma computadora. Este proyecto usa el 5174.</p><p><strong>Enlace de acceso <code>http://localhost:5174/</code></strong>: esta direccion significa &quot;acceder a la pagina web con numero 5174 en esta computadora&quot;. Abriendo este enlace en el navegador podras ver el efecto.</p><p><strong>Explicacion de este escenario</strong>: el sistema originalmente queria usar el puerto 5173, pero ese numero ya estaba en uso, asi que cambio automaticamente al 5174. Esto es normal.</p><p><strong>Instrucciones de operacion</strong>: abre el navegador, introduce <code>http://localhost:5174/</code> en la barra de direcciones y presiona Enter para ver la pagina del proyecto actual.</p></div><p>Despues de confirmar todo, espera un momento a que el agente termine de ejecutarse, y podemos obtener el siguiente resultado: <img src="'+_+'" alt=""></p><p>Podemos ver que ya hay una vista preliminar de las funcionalidades, pero la pagina frontend se ve muy fea. En este momento podemos intentar hablar directamente con la IA para optimizar la visualizacion de la interfaz: <img src="'+A+'" alt=""></p><p>Despues de optimizar, podemos obtener una interfaz mas bonita: <img src="'+k+'" alt=""></p><p>Puedes modificar las funcionalidades de la pagina web segun tus necesidades; puedes adjuntar capturas de pantalla y preguntar libremente, por ejemplo: &quot;Todavia no necesito la funcion de importacion en lote, ayudame a quitarla&quot;, &quot;Hay demasiadas cosas que rellenar a la izquierda, ayudame a dejar solo xxxxx&quot;. Incluso puedes referenciar otros sitios web maduros; por ejemplo, aqui podemos referirnos directamente a un producto de diseno de Google (puedes pegar una captura de pantalla de un sitio web maduro que te guste): <img src="'+j+'" alt=""></p><p>Finalmente podemos obtener: <img src="'+I+'" alt=""></p><h3 id="_2-3-que-hacer-cuando-hay-errores" tabindex="-1">2.3 Que hacer cuando hay errores <a class="header-anchor" href="#_2-3-que-hacer-cuando-hay-errores" aria-label="Permalink to “2.3 Que hacer cuando hay errores”">​</a></h3><p>En la practica, encontrar errores es inevitable; es un fenomeno normal y no significa que hayas hecho algo mal. No necesitas entender el error; solo pasa &quot;lo que ves&quot; completamente a la IA.</p><p>Solo hay tres formas comunes de manejarlos:</p><ul><li><p><strong>Forma 1: Error en la pagina o terminal</strong> Cuando la pagina se pone roja, queda en blanco, o aparecen un monton de letras rojas en la terminal, simplemente haz una captura de pantalla o copia toda la informacion del error y enviasela a la IA para que te ayude a repararlo.</p></li><li><p><strong>Forma 2: La funcionalidad no esta bien pero no hay error</strong> Por ejemplo, el boton no responde, los datos no se muestran, los estilos estan desordenados. Describe en lenguaje llano &quot;que esta pasando ahora + lo que tu querias&quot;, y si es necesario, anade una captura de pantalla.</p></li><li><p><strong>Forma 3: No estas seguro de si hay algun problema</strong> Puedes preguntar directamente a la IA: &quot;Ayudame a revisar si esta funcionalidad tiene algun problema obvio, si necesita ajustes.&quot;</p></li></ul><h4 id="_2-3-1-preguntas-frecuentes-de-principiantes" tabindex="-1">2.3.1 Preguntas frecuentes de principiantes <a class="header-anchor" href="#_2-3-1-preguntas-frecuentes-de-principiantes" aria-label="Permalink to “2.3.1 Preguntas frecuentes de principiantes”">​</a></h4><ul><li><p><strong>P: No se donde esta la informacion del error?</strong></p></li><li><p>R: Generalmente, mira todas las &quot;letras rojas&quot;. En la terminal, la consola o la pagina, busca las indicaciones en rojo, selecciona todo y copialo para la IA.</p></li><li><p><strong>P: Que hago si la IA lo arregla pero sigue dando el mismo error?</strong></p></li><li><p>R: Esto es comun. Sigue haciendo capturas de pantalla o copiando la ultima informacion del error y enviasela, para que lo repare aun mas basandose en la ultima modificacion.</p></li><li><p><strong>P: Necesito entender completamente el plan de reparacion de la IA?</strong></p></li><li><p>R: No necesitas entenderlo todo de una vez. Puedes centrarte en uno o dos puntos cada vez; con el tiempo, iras entendiendo cada vez mas codigo, como cuando acumulas vocabulario en ingles.</p></li><li><p><strong>P: Despues de muchas modificaciones, el problema sigue sin resolverse?</strong></p></li><li><p>R: Puedes intentar:</p><ul><li>Usar la funcion de &quot;rollback de version&quot; del IDE, encontrar el boton de deshacer en el chat del agente, volver a una version que funcionaba y empezar de nuevo;</li><li>Cambiar de modelo o ajustar el prompt, describiendo el fenomeno y la informacion del error de forma mas especifica;</li><li>Empaquetar &quot;codigo actual + log de errores + comportamiento esperado&quot; y enviarlo todo de una vez a la IA, para que reestructure completamente la parte problematica.</li></ul></li></ul><h2 id="_3-expandir-de-aplicacion-de-una-sola-pagina-a-multipagina" tabindex="-1">3. Expandir de aplicacion de una sola pagina a multipagina <a class="header-anchor" href="#_3-expandir-de-aplicacion-de-una-sola-pagina-a-multipagina" aria-label="Permalink to “3. Expandir de aplicacion de una sola pagina a multipagina”">​</a></h2>',45)),e("div",M,[n(l,null,{default:s(()=>[n(t,{active:2,items:[{title:"Analisis de necesidades",description:"De lo vago a lo concreto"},{title:"Validacion de una pagina",description:"La funcionalidad central toma forma"},{title:"Expansion multipagina",description:"Completar la estructura de la aplicacion"},{title:"Mejora estetica",description:"Mejorar la experiencia del usuario"}]})]),_:1})]),a[11]||(a[11]=i('<p>Cuando la logica de la funcionalidad central esta basicamente generada, podemos generar el resto del contenido. Por ejemplo, en este punto, si hacemos clic en configuracion o en algunos botones, no hacen nada.</p><p>Puedes pedirle a la IA que revise segun los requisitos del prompt de negocio y genere las partes que faltan, o pedirle directamente que complete las paginas no implementadas. Tambien puedes especificar una pagina para que la IA la complete, hasta que las paginas se puedan hacer clic y las funcionalidades puedan interactuar normalmente: <img src="'+P+'" alt=""></p><p>Despues de esperar un momento, podemos ver que el programa ya ha completado multiples paginas y funcionalidades interactivas basandose en lo anterior: <img src="'+E+'" alt=""></p><p><img src="'+z+'" alt=""></p><p>En este punto solo necesitas hacer clic manualmente en cada funcion y boton que te interese, asegurandote de que la interaccion sea normal. Si hay funcionalidades que no se pueden interactuar, puedes comunicarte con la IA para que te ayude a repararlas.</p><h2 id="_4-hacer-que-el-prototipo-parezca-profesional" tabindex="-1">4. Hacer que el prototipo &quot;parezca profesional&quot; <a class="header-anchor" href="#_4-hacer-que-el-prototipo-parezca-profesional" aria-label="Permalink to “4. Hacer que el prototipo &quot;parezca profesional&quot;”">​</a></h2>',6)),e("div",U,[n(l,null,{default:s(()=>[n(t,{active:3,items:[{title:"Analisis de necesidades",description:"De lo vago a lo concreto"},{title:"Validacion de una pagina",description:"La funcionalidad central toma forma"},{title:"Expansion multipagina",description:"Completar la estructura de la aplicacion"},{title:"Mejora estetica",description:"Mejorar la experiencia del usuario"}]})]),_:1})]),a[12]||(a[12]=i(`<p>Despues de tener la estructura multipagina, el ultimo paso es hacer que el prototipo pase de &quot;funcional&quot; a &quot;comodo de usar y profesional&quot;. Para ello, necesitamos experimentar todo el flujo (flujo de usuario) y hacer que la IA repare las partes que no funcionan, para que podamos simular un nuevo usuario recorriendo todo el flujo desde cero cada vez que actualizamos, obteniendo el resultado esperado.</p><p>Recordemos los requisitos iniciales:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. Ayudar a operaciones a generar en lote la primera version de borradores de imagenes y textos:</span></span>
<span class="line"><span>- **Entrada (soporta subida directa e importacion en lote de materiales):**</span></span>
<span class="line"><span>  - Informacion basica del producto: nombre, categoria, marca, material, talla, color, publico objetivo, etc.;</span></span>
<span class="line"><span>  - Imagenes del producto: foto con fondo blanco / foto con escenario simple;</span></span>
<span class="line"><span>  - Cada generacion soporta subir capturas de productos exitosos anteriores o enlaces de referencia;</span></span>
<span class="line"><span>  - Soporta importar en lote via Excel, o rellenar/subir online en la pagina.</span></span>
<span class="line"><span>  - Soporta especificar en la pagina si guardar los materiales en la biblioteca, para facilitar el proximo uso</span></span>
<span class="line"><span>- **Salida (contenido que se puede publicar directamente o con pequenos cambios):**</span></span>
<span class="line"><span>  - Para cada producto, un borrador de imagen principal &quot;presentable, con puntos de venta basicos&quot;;</span></span>
<span class="line"><span>  - Un titulo &quot;con estructura razonable y palabras clave centrales&quot; + 1-2 frases de puntos de venta.</span></span>
<span class="line"><span>- **Cambio esperado en la forma de uso:**</span></span>
<span class="line"><span>  Pasar de empezar cada lote desde cero a pasar un lote de productos al sistema y usar los borradores generados para filtrar y ajustar.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Guardar las buenas soluciones como una biblioteca de plantillas reutilizables:</span></span>
<span class="line"><span>- **Que se puede guardar?**</span></span>
<span class="line"><span>  - Cualquier salida que las operaciones consideren &quot;buena&quot; se puede guardar con un clic:</span></span>
<span class="line"><span>    - Puede ser la combinacion completa de &quot;imagen principal + titulo + puntos de venta&quot;;</span></span>
<span class="line"><span>    - O solo una parte, como una estructura de titulo o un texto de puntos de venta.</span></span>
<span class="line"><span>- **Que se puede hacer despues de guardar?**</span></span>
<span class="line"><span>  - **Reutilizar:**</span></span>
<span class="line"><span>    - Usar esta entrada guardada para generar un nuevo lote de imagenes y textos con los parametros de nuevos productos;</span></span>
<span class="line"><span>    - O sobre el mismo producto, generar multiples variantes basadas en la plantilla para hacer tests A/B.</span></span>
<span class="line"><span>  - **Editar:**</span></span>
<span class="line"><span>    - Modificar directamente el titulo / texto de puntos de venta;</span></span>
<span class="line"><span>    - Si se soporta edicion de imagen, se pueden ajustar elementos como texto y pegatinas en la imagen principal.</span></span>
<span class="line"><span>  - **Gestionar:**</span></span>
<span class="line"><span>    - Poner nombre a las entradas guardadas, etiquetar (ej. &quot;plantilla de imagen principal de bolsos de hombre&quot;, &quot;estructura de titulo de promocion&quot;), soportar clasificacion por tienda para facilitar la busqueda posterior.</span></span>
<span class="line"><span>- **Como usarlo la proxima vez que se publique un producto nuevo?**</span></span>
<span class="line"><span>  - Despues de importar productos nuevos, las operaciones pueden elegir:</span></span>
<span class="line"><span>    - Usar la logica por defecto del sistema, o</span></span>
<span class="line"><span>    - Especificar &quot;usar una de mis plantillas guardadas para generar&quot;;</span></span>
<span class="line"><span>  - El sistema basandose en los datos del nuevo producto, aplica automaticamente la estructura y el estilo de la plantilla, generando nuevos borradores de imagen principal + titulo + puntos de venta.</span></span></code></pre></div><p>Si cada vez que pruebas necesitas crear datos nuevos, esto lleva mucho tiempo. En este caso, normalmente usamos algo llamado &quot;datos de prueba&quot;. Podemos comunicarnos con la IA de la siguiente manera, para que genere en la interfaz una entrada rapida de datos de prueba que nos permita verificar que todas las funcionalidades funcionan correctamente:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Necesito probar el proceso de uso del usuario, asegurandome de que pueda completarse totalmente. Por favor genera una entrada de datos de prueba basandote en los siguientes requisitos, para que pueda hacer clic y probar rapidamente si todo el flujo funciona normalmente:</span></span>
<span class="line"><span>1. Ayudar a operaciones a generar en lote la primera version de borradores de imagenes y textos:</span></span>
<span class="line"><span>- **Entrada (soporta subida directa e importacion en lote de materiales):**</span></span>
<span class="line"><span>  - Informacion basica del producto: nombre, categoria, marca, material, talla, color, publico objetivo, etc.;</span></span>
<span class="line"><span>  - Imagenes del producto: foto con fondo blanco / foto con escenario simple;</span></span>
<span class="line"><span>  - Cada generacion soporta subir capturas de productos exitosos anteriores o enlaces de referencia;</span></span>
<span class="line"><span>  - Soporta importar en lote via Excel, o rellenar/subir online en la pagina.</span></span>
<span class="line"><span>  - Soporta especificar en la pagina si guardar los materiales en la biblioteca, para facilitar el proximo uso</span></span>
<span class="line"><span>- **Salida (contenido que se puede publicar directamente o con pequenos cambios):**</span></span>
<span class="line"><span>  - Para cada producto, un borrador de imagen principal &quot;presentable, con puntos de venta basicos&quot;;</span></span>
<span class="line"><span>  - Un titulo &quot;con estructura razonable y palabras clave centrales&quot; + 1-2 frases de puntos de venta.</span></span>
<span class="line"><span>- **Cambio esperado en la forma de uso:**</span></span>
<span class="line"><span>  Pasar de empezar cada lote desde cero a pasar un lote de productos al sistema y usar los borradores generados para filtrar y ajustar.</span></span></code></pre></div><p>Es facil obtener resultados (si crees que un dato es muy poco, puedes pedirle a la IA que genere multiples casos de prueba): <img src="`+C+'" alt=""></p><p>Despues de hacer clic, obtenemos el resultado: <img src="'+S+'" alt=""></p><p>En este punto lo que obtenemos directamente es el resultado, no hay un &quot;proceso de generacion simulado&quot;. Si queremos simular un proceso de generacion real, podemos hablar directamente con la IA: &quot;Por favor simula un proceso de generacion real, que me des el resultado despues de un rato al hacer clic.&quot; <img src="'+D+'" alt=""></p><p>Despues de verificar la funcionalidad de generacion, tambien debemos asegurarnos de que la funcionalidad de la biblioteca de plantillas funciona correctamente. En la tarjeta de generacion de la pagina podemos ver que la funcion de guardado de plantillas no se ha implementado; necesitamos tener una conversacion mas profunda con la IA: &quot;Por favor ayudame a asegurarme de que el requisito [pega aqui el contenido del punto 2 de arriba] funciona correctamente, que se pueda hacer clic en un resultado para guardar la plantilla correspondiente, y que al abrirlo se puedan ver los parametros de generacion&quot;</p><p>La generacion a menudo no se consigue de una sola vez; frecuentemente hay que hacer capturas de pantalla para corregir: <img src="'+T+'" alt=""></p><p>Finalmente obtenemos el resultado esperado: <img src="'+R+'" alt=""></p><p>Ademas de experimentar manualmente el flujo de requisitos, tambien puedes pedirle a la IA que haga directamente una verificacion de requisitos, por ejemplo:</p><ul><li>&quot;Por favor compara con mis requisitos originales, revisa si la aplicacion actual ya cubre todas las funcionalidades centrales.&quot;</li><li>&quot;Ayudame a hacer una lista de funcionalidades, indicando cuales ya estan completadas, cuales aun no estan implementadas o tienen una experiencia insuficiente.&quot;</li></ul><p>La IA generalmente generara un checklist, y puedes pensar si necesitas seguir mejorando basandote en los resultados. Despues de iteraciones repetidas, puedes obtener un resultado de prototipo bastante completo.</p><h2 id="_5-asignacion-replica-tu-propio-espacio-de-trabajo-de-e-commerce-de-tiktok" tabindex="-1">5. Asignacion: replica tu propio espacio de trabajo de e-commerce de TikTok <a class="header-anchor" href="#_5-asignacion-replica-tu-propio-espacio-de-trabajo-de-e-commerce-de-tiktok" aria-label="Permalink to “5. Asignacion: replica tu propio espacio de trabajo de e-commerce de TikTok”">​</a></h2>',15)),n(p,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:s(()=>[...a[2]||(a[2]=[e("div",{style:{"font-weight":"bold","font-size":"16px"}},"Mision de desafio: replica el espacio de trabajo de materiales de e-commerce",-1)])]),default:s(()=>[a[3]||(a[3]=e("p",null," Referenciando los prompts y el contenido de esta leccion, completa un ciclo cerrado: ",-1)),a[4]||(a[4]=e("ul",null,[e("li",null,[e("strong",null,"Practica de ciclo cerrado completo"),e("ul",null,[e("li",null,"Generacion de prompts a partir del analisis de negocio -> generacion de prototipo de una pagina -> generacion de prototipo multipagina")])]),e("li",null,[e("strong",null,"Compartir resultados"),e("ul",null,[e("li",null,"Haz capturas de pantalla de tu programa y compartelas con todos")])]),e("li",null,[e("strong",null,"Pregunta de reflexion"),e("ul",null,[e("li",null,'Para la proxima seccion "integrar capacidades de LLM y generacion de texto a imagen", piensa con antelacion: como podrias integrar capacidades como "IA que escribe textos / genera imagenes / genera scripts" en tu espacio de trabajo?')])])],-1))]),_:1}),a[13]||(a[13]=e("h2",{id:"proximo-paso",tabindex:"-1"},[o("Proximo paso "),e("a",{class:"header-anchor",href:"#proximo-paso","aria-label":"Permalink to “Proximo paso”"},"​")],-1)),a[14]||(a[14]=e("p",null,"En la siguiente seccion, construiremos sobre este espacio de trabajo de produccion de contenido e integraremos capacidades especificas de IA (texto a texto, imagen a texto, texto a imagen), por ejemplo:",-1)),a[15]||(a[15]=e("ul",null,[e("li",null,"Generar automaticamente un primer borrador de texto y multiples opciones de titulos para una tarea de contenido"),e("li",null,"Generar automaticamente un borrador de imagen de acompanamiento basandose en la descripcion de la tarea (texto a imagen)"),e("li",null,"Clasificar y resumir automaticamente las tareas de contenido historicas, ayudandote a planificar los temas de la proxima campana")],-1)),n(m,{title:"Sigue aprendiendo",description:"Se recomienda seguir el orden 'integrar capacidades de IA -> ciclo completo de proyecto -> ingenieria de diseno'.",items:L(c)},null,8,["items"])])}}});export{B as __pageData,J as default};
